<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {getModelSettings,saveModelSettings,testModelSettings,type ModelConfig,type ModelTarget} from '../api/client'
const settings=ref<{generation:ModelConfig;embedding:ModelConfig}|null>(null),busy=ref(false),message=ref(''),error=ref('')
function config(target:ModelTarget){return settings.value?.[target]}
async function load(){try{settings.value=await getModelSettings()}catch(e:any){error.value=e.message}}
async function save(target:ModelTarget){const c=config(target);if(!c)return;busy.value=true;error.value='';message.value='';try{if(target==='embedding'&&c.provider==='OPENAI_COMPATIBLE'){const before=await getModelSettings(),old=before.embedding;const changes=!old.explicitlyConfigured||old.provider!==c.provider||old.baseUrl!==c.baseUrl||old.model!==c.model||old.embeddingDimension!==c.embeddingDimension;if(changes&&!confirm('保存后，已有资料将重新嵌入；提取出的文档片段会发送给配置的兼容公共 API。继续吗？'))return}const r=await saveModelSettings(target,c);settings.value=r.settings;message.value=target==='embedding'&&r.reindexing?'嵌入配置已保存，资料正在重新建立索引。':'配置已保存。'}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function test(target:ModelTarget){busy.value=true;error.value='';message.value='';try{const r=await testModelSettings(target);message.value=`${target==='generation'?'生成':'嵌入'}连接成功：${r.provider} / ${r.model}（${r.elapsedMs} ms）`}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="settings-page"><div class="card"><h2>模型服务设置</h2><p>生成和嵌入配置彼此独立。API Key 只从服务启动环境变量读取，设置页仅保存环境变量引用名；修改进程环境变量后需重启后端。</p><p class="privacy-note">公共嵌入服务会收到上传、重试或重建索引时的文档片段，以及每次提问的查询文本；公共生成服务会收到问题和检索到的片段。应用会在上传、重试、重建索引或提问前分别说明并请求确认。Ollama 流程不会自动切换到公共服务。</p><p v-if="message" class="success">{{message}}</p><p v-if="error" class="error">{{error}}</p></div><div v-if="settings" class="settings-grid"><article v-for="target in (['generation','embedding'] as ModelTarget[])" :key="target" class="card"><h3>{{target==='generation'?'生成模型':'嵌入模型'}}</h3><label>服务类型<select v-model="config(target)!.provider"><option value="OLLAMA">Ollama 本地服务</option><option value="OPENAI_COMPATIBLE">OpenAI 兼容 API</option></select></label><label>服务地址<input v-model="config(target)!.baseUrl" placeholder="http://127.0.0.1:11434"></label><label>模型名称<input v-model="config(target)!.model"></label><label v-if="config(target)!.provider==='OPENAI_COMPATIBLE'">API Key 环境变量引用<input v-model="config(target)!.apiKeyRef" placeholder="OPENAI_API_KEY"><small>{{config(target)!.apiKeyConfigured?'已在进程环境中配置':'密钥由应用启动环境提供，不在此页录入'}}</small></label><label>超时（毫秒）<input type="number" min="1000" max="120000" v-model.number="config(target)!.timeoutMs"></label><label v-if="target==='embedding'">向量维度<input type="number" min="1" max="8192" v-model.number="config(target)!.embeddingDimension"><small>维度须与嵌入模型输出一致。更换模型、服务或维度后系统会重建资料索引。</small></label><template v-if="target==='generation'"><label>温度<input type="number" min="0" max="2" step="0.1" v-model.number="config(target)!.temperature"></label><label>最大输出 Token<input type="number" min="1" max="32768" v-model.number="config(target)!.maxTokens"></label></template><div class="settings-actions"><button :disabled="busy" @click="save(target)">保存配置</button><button class="secondary" :disabled="busy" @click="test(target)">测试连接</button></div></article></div></section></template>
